102	    using TensorType = RetType;
103	    static constexpr std::size_t number = N;
104	    // for IN_OUT scenario. Two `Param`s point to the same GM
105	    static constexpr std::size_t inplaceNumber = RN;
106	    static constexpr ParamUsage usage = U;
107	
108	    template <typename W>
109	    constexpr auto operator=(Expression<W>)
110	    {
111	        static_assert(
112	            Util::AlwaysFalse_v<W>, "[ERROR]: [Atvoss][Expression] Please use Expression<Param> for assignment");
113	    }
