217	template <typename UnsortedLst>
218	struct SortedParams {
219	    static constexpr std::size_t size = Atvoss::Util::Size_v<UnsortedLst>;
220	
221	    template <std::size_t Number>
222	    struct GetByNumber {
223	        static constexpr std::size_t pos =
224	            Atvoss::Util::Find_v<Atvoss::CheckVarNum<Number>::template Checker, UnsortedLst>;
225	        using Type = Atvoss::Util::Get_t<UnsortedLst, pos>;
226	    };
227	
228	    // Sort ...
229	    template <std::size_t... Numbers>
230	    static constexpr auto BuildSortedList(std::index_sequence<Numbers...>)
231	    {
232	        return Util::TypeList<typename GetByNumber<Numbers + 1>::Type...>{};
233	    }
234	
235	public:
236	    using Type = decltype(BuildSortedList(std::make_index_sequence<size>{}));
237	};
