915	    struct FindByIndex<I, TypeList<Head, Tail...>> {
916	    private:
917	        using TailResult = FindByIndex<I, TypeList<Tail...>>;
918	
919	    public:
920	        static constexpr bool found = (Head::index == I) || TailResult::found;
921	
